stimulus.text:
SELECT 이름
FROM   사원
WHERE  부서번호 NOT IN (SELECT 부서번호 FROM 부서);

SELECT *
FROM   급여      -- 컬럼: 부서, 직급, 연봉
( 빈칸 );

SELECT 급여,
FIRST_VALUE(급여) OVER (ORDER BY 급여) AS 결과
FROM   사원;

SELECT *
FROM   회원
WHERE  (사번, 회원번호) IN ((10005, 2003), (10007, 2005));

SELECT 이름,
NTILE(3) OVER (ORDER BY 급여 DESC) AS 그룹
FROM   사원;

SELECT *
FROM (SELECT 부서, 직급 FROM 사원)
PIVOT (COUNT(*) FOR 직급 IN ('사원' AS 사원, '대리' AS 대리, '과장' AS 과장));

SELECT 사원명
FROM 사원
WHERE 부서번호 = (SELECT 부서번호 FROM 부서 WHERE 부서명 = '영업');

SELECT 상품ID
FROM   상품 A
WHERE  NOT EXISTS (
SELECT 1 FROM 주문 B WHERE B.상품ID = A.상품ID
);

SELECT EXTRACT(MONTH FROM 일자) FROM 이벤트
UNION
SELECT EXTRACT(YEAR  FROM 일자) FROM 이벤트;

SELECT SUM(A.컬럼2)
FROM   테이블1 A
INNER JOIN 테이블2 B ON A.컬럼1 = B.컬럼1;

CREATE TABLE 상품 (
상품번호 INT IDENTITY(1,1),
수량     INT CHECK (수량 > 0)
);
INSERT INTO 상품 (수량) VALUES (-1);
INSERT INTO 상품 (수량) VALUES (0);
INSERT INTO 상품 (수량) VALUES (1);

SELECT COUNT(*) FROM 상품;
